require(['gram/gram'], function(gram) {

    var GramShell = gram.view.system.GramShell;
    var Polyline = gram.view.widget.svg.Polyline;
    var Svg = gram.view.widget.svg.Svg;

    var shell = new GramShell('container');
    var svg = new Svg();
    shell.contents(svg);

    var p1 = new Polyline();
    p1.cursor('move')
        .border(2, 'salmon')
        .points(100,100,140,140,100,180);
    svg.append(p1);

});
